// The snapshot signature, checked by the Sui SDK: a snapshot signed by the Rust signer must verify as a standard Sui
// personal message and name the same address, so anyone can verify a snapshot with ordinary Sui tooling (ADR-0007).
// The fixture is generated by `cargo run -p content-hub-core --example gen-snapshot-fixture` and signed by a TEST key;
// the service's own test fails if the committed file differs from what the code produces.
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { verifyPersonalMessageSignature } from '@mysten/sui/verify'
import { describe, expect, it } from 'vitest'

const fixture = JSON.parse(readFileSync(new URL('./snapshot-fixture.json', import.meta.url), 'utf8')) as {
  address: string
  sha256: string
  message_base64: string
  message_utf8_length: number
  signature: string
}
const message = new Uint8Array(Buffer.from(fixture.message_base64, 'base64'))

describe('the roadmap snapshot signature', () => {
  it('is a valid Sui personal-message signature by the stated address', async () => {
    const publicKey = await verifyPersonalMessageSignature(message, fixture.signature)
    expect(publicKey.toSuiAddress()).toBe(fixture.address)
  })

  it('signs exactly the bytes whose SHA-256 is recorded, and those bytes are canonical JSON', () => {
    expect(message.length).toBe(fixture.message_utf8_length)
    expect(createHash('sha256').update(message).digest('hex')).toBe(fixture.sha256)
    const text = new TextDecoder().decode(message)
    expect(text).not.toMatch(/\s{2}|\n/) // compact
    const doc = JSON.parse(text) as Record<string, unknown>
    expect(doc.schema).toBe('content-hub.roadmap-snapshot/1')
    // Keys are sorted at the top level and re-serialising the parsed document gives the same bytes.
    expect(Object.keys(doc)).toEqual([...Object.keys(doc)].sort())
    const sortDeep = (v: unknown): unknown =>
      Array.isArray(v)
        ? v.map(sortDeep)
        : v && typeof v === 'object'
          ? Object.fromEntries(Object.entries(v as Record<string, unknown>).sort(([a], [b]) => (a < b ? -1 : 1)).map(([k, x]) => [k, sortDeep(x)]))
          : v
    expect(JSON.stringify(sortDeep(doc))).toBe(text)
  })

  it('does not verify for a changed message or a changed signature', async () => {
    const changed = new Uint8Array(message)
    changed[changed.length - 2] ^= 1
    await expect(verifyPersonalMessageSignature(changed, fixture.signature)).rejects.toThrow()
    const sig = Buffer.from(fixture.signature, 'base64')
    sig[20] ^= 1
    await expect(verifyPersonalMessageSignature(message, sig.toString('base64'))).rejects.toThrow()
  })
})
